package com.sk.framework.common.dto;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonInclude;

import java.time.LocalDateTime;

/**
 * 표준 API 응답 포맷
 * 
 * <p>모든 API 응답에 일관된 형식을 제공합니다.</p>
 * <p>성공/실패 여부, 메시지, 데이터, 타임스탬프를 포함합니다.</p>
 * 
 * <pre>
 * {@code
 * // 성공 응답
 * ApiResponse<User> response = ApiResponse.success(user, "User found successfully");
 * 
 * // 실패 응답
 * ApiResponse<Void> response = ApiResponse.error("User not found", "USER_NOT_FOUND");
 * }
 * </pre>
 * 
 * @param <T> 응답 데이터의 타입
 * 
 * @author SK Framework Team
 * @since 1.0.0
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public class ApiResponse<T> {

    /**
     * 응답 성공 여부
     */
    private boolean success;

    /**
     * 응답 메시지
     */
    private String message;

    /**
     * 응답 데이터
     */
    private T data;

    /**
     * 에러 코드 (실패 시)
     */
    private String errorCode;

    /**
     * 응답 타임스탬프
     */
    @JsonFormat(pattern = "yyyy-MM-dd HH:mm:ss")
    private LocalDateTime timestamp;

    /**
     * 기본 생성자
     */
    public ApiResponse() {
        this.timestamp = LocalDateTime.now();
    }

    /**
     * 전체 필드 생성자
     * 
     * @param success 성공 여부
     * @param message 메시지
     * @param data 데이터
     * @param errorCode 에러 코드
     */
    public ApiResponse(boolean success, String message, T data, String errorCode) {
        this();
        this.success = success;
        this.message = message;
        this.data = data;
        this.errorCode = errorCode;
    }

    /**
     * 성공 응답을 생성합니다.
     * 
     * @param <T> 데이터 타입
     * @param data 응답 데이터
     * @return 성공 응답
     */
    public static <T> ApiResponse<T> success(T data) {
        return success(data, "Success");
    }

    /**
     * 성공 응답을 생성합니다.
     * 
     * @param <T> 데이터 타입
     * @param data 응답 데이터
     * @param message 성공 메시지
     * @return 성공 응답
     */
    public static <T> ApiResponse<T> success(T data, String message) {
        return new ApiResponse<>(true, message, data, null);
    }

    /**
     * 데이터 없는 성공 응답을 생성합니다.
     * 
     * @param message 성공 메시지
     * @return 성공 응답
     */
    public static ApiResponse<Void> success(String message) {
        return new ApiResponse<>(true, message, null, null);
    }

    /**
     * 실패 응답을 생성합니다.
     * 
     * @param message 실패 메시지
     * @return 실패 응답
     */
    public static ApiResponse<Void> error(String message) {
        return error(message, "UNKNOWN_ERROR");
    }

    /**
     * 실패 응답을 생성합니다.
     * 
     * @param message 실패 메시지
     * @param errorCode 에러 코드
     * @return 실패 응답
     */
    public static ApiResponse<Void> error(String message, String errorCode) {
        return new ApiResponse<>(false, message, null, errorCode);
    }

    /**
     * 실패 응답을 생성합니다. (데이터 포함)
     * 
     * @param <T> 데이터 타입
     * @param message 실패 메시지
     * @param errorCode 에러 코드
     * @param data 추가 데이터 (예: 검증 오류 세부사항)
     * @return 실패 응답
     */
    public static <T> ApiResponse<T> error(String message, String errorCode, T data) {
        return new ApiResponse<>(false, message, data, errorCode);
    }

    // Getters and Setters

    public boolean isSuccess() {
        return success;
    }

    public void setSuccess(boolean success) {
        this.success = success;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public T getData() {
        return data;
    }

    public void setData(T data) {
        this.data = data;
    }

    public String getErrorCode() {
        return errorCode;
    }

    public void setErrorCode(String errorCode) {
        this.errorCode = errorCode;
    }

    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(LocalDateTime timestamp) {
        this.timestamp = timestamp;
    }

}

package com.sk.framework.common.dto;

import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

/**
 * @className    : ApiResponse
 * @description  : 표준 API 응답 구조 - Rule에 따른 통일된 응답 포맷
 * @modification : 2025.08.21(프레임워크팀) Rule 업데이트에 따른 구현
 * @author       : SK Framework Team
 * @date         : 2025.08.21
 * @version      : 2.0
 */
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class ApiResponse<T> {
    
    private boolean success;
    private String code;
    private String message;
    private T data;
    
    /**
     * 성공 응답 생성 (데이터 없음)
     */
    public static <T> ApiResponse<T> success() {
        return ApiResponse.<T>builder()
                .success(true)
                .code("SUCCESS")
                .message("요청이 성공적으로 처리되었습니다.")
                .build();
    }
    
    /**
     * 성공 응답 생성 (데이터 포함)
     */
    public static <T> ApiResponse<T> success(T data) {
        return ApiResponse.<T>builder()
                .success(true)
                .code("SUCCESS")
                .message("요청이 성공적으로 처리되었습니다.")
                .data(data)
                .build();
    }
    
    /**
     * 성공 응답 생성 (메시지 커스터마이징)
     */
    public static <T> ApiResponse<T> success(String message, T data) {
        return ApiResponse.<T>builder()
                .success(true)
                .code("SUCCESS")
                .message(message)
                .data(data)
                .build();
    }
    
    /**
     * 실패 응답 생성
     */
    public static <T> ApiResponse<T> failure(String code, String message) {
        return ApiResponse.<T>builder()
                .success(false)
                .code(code)
                .message(message)
                .build();
    }
    
    /**
     * 실패 응답 생성 (데이터 포함)
     */
    public static <T> ApiResponse<T> failure(String code, String message, T data) {
        return ApiResponse.<T>builder()
                .success(false)
                .code(code)
                .message(message)
                .data(data)
                .build();
    }
}

package com.sk.sample.repository;

import com.sk.sample.entity.User;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * @className    : UserRepository
 * @description  : 사용자 Repository - Rule에 따른 도메인별 Repository 구현
 * @modification : 2025.08.21(프레임워크팀) Rule 업데이트에 따른 구현
 * @author       : SK Framework Team
 * @date         : 2025.08.21
 * @version      : 2.0
 */
@Repository
public interface UserRepository extends JpaRepository<User, Long> {

    /**
     * 이메일로 사용자 조회
     */
    Optional<User> findByEmail(String email);

    /**
     * 사용자명으로 사용자 목록 조회
     */
    List<User> findByUsernameContaining(String username);

    /**
     * 상태별 사용자 목록 조회
     */
    List<User> findByStatus(User.UserStatus status);

    /**
     * 사용자명과 상태로 사용자 존재 여부 확인
     */
    boolean existsByUsernameAndStatus(String username, User.UserStatus status);

    /**
     * 복합 검색 조건으로 사용자 목록 조회
     */
    @Query("SELECT u FROM User u WHERE " +
           "(:username IS NULL OR u.username LIKE %:username%) AND " +
           "(:email IS NULL OR u.email LIKE %:email%) AND " +
           "(:phone IS NULL OR u.phone LIKE %:phone%) AND " +
           "(:status IS NULL OR u.status = :status)")
    List<User> findBySearchConditions(@Param("username") String username,
                                     @Param("email") String email,
                                     @Param("phone") String phone,
                                     @Param("status") User.UserStatus status);
}
